# Try: replace each cell with majority of its 8 neighbors
def majority_rule(grid):
    n = len(grid)
    m = len(grid[0])
    output = [[0] * m for _ in range(n)]
    for r in range(n):
        for c in range(m):
            counts = {5: 0, 1: 0}
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        counts[grid[nr][nc]] += 1
            if counts[5] > counts[1]:
                output[r][c] = 5
            elif counts[1] > counts[5]:
                output[r][c] = 1
            else:
                # Tie - keep original
                output[r][c] = grid[r][c]
    return output

